<script setup lang="ts">import { ref, onMounted } from 'vue'; import axios from 'axios'; const stats = ref<any[]>([]); const assets = ref<any[]>([]); const dashboard = ref<any>({}); onMounted(async () => { const [d, a] = await Promise.all([axios.get('/api/dashboard'), axios.get('/api/assets')]); dashboard.value = d.data; stats.value = [['assets', '素材'], ['scripts', '脚本'], ['templates', '模板'], ['mix_projects', '混剪方案'], ['videos', '视频作品']].map(([key, label]) => ({ key, label, value: d.data[key] || 0 })); assets.value = a.data.slice(0, 5); });</script>
